func init() {
	for _, names := range onlineStubShims {
		for _, n := range names {
			if _, dup := CanonicalShims[n]; !dup {
				CanonicalShims[n] = "shim_" + n
			}
		}
	}
	for _, n := range cppWebApiShims {
		if _, dup := CanonicalShims[n]; !dup {
			CanonicalShims[n] = "shim_" + n
		}
	}
	for nid, shim := range cppWebApiNIDShims {
		if _, dup := CanonicalShims[nid]; !dup {
			CanonicalShims[nid] = shim
		}
	}
}
